import java.net.*;
public class Main {
  public static void main(String[] args) throws Exception {
    try {
      Socket s = new Socket();
      s.connect(new InetSocketAddress("93.184.216.34", 80), 3000);
      System.out.println("connected!");
      s.close();
    } catch(Exception e) {
      System.out.println("error: " + e.getMessage());
    }
  }
}
